// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CallContextChecker} from "solady/utils/CallContextChecker.sol";
import {Registry, ASSET_NOT_FOUND} from "./Registry.sol";
import {RegistryStorage} from "./RegistryStorage.sol";
import {GovernanceCore} from "./governance/GovernanceCore.sol";
import {IRegistryFacet} from "./interfaces/IRegistryFacet.sol";
import {ChainAddress} from "./utils/ChainAddress.sol";
import {indexKey} from "./utils/IndexKey.sol";
import {Paging} from "./utils/Paging.sol";
import {SeriesValidation} from "./utils/SeriesValidation.sol";

/// @dev Maximum listings a new asset carries.
uint256 constant MAX_NEW_ASSET_LISTINGS = 32;

/// @dev Op type of an asset index's risk parameters.
bytes32 constant OP_RISK_PARAMETERS = keccak256("Registry.RISK_PARAMETERS");

/// @dev Op type of a new asset at the next index with its initial listings.
bytes32 constant OP_ADD_NEW_ASSET = keccak256("Registry.ADD_NEW_ASSET");

/// @dev Op type of a listing under an existing asset.
bytes32 constant OP_ADD_FUNGIBLE_ASSET_LISTING = keccak256("Registry.ADD_FUNGIBLE_ASSET_LISTING");

/// @dev Op type of an entry's maximum deposit.
bytes32 constant OP_ADMISSION_CAP = keccak256("Registry.ADMISSION_CAP");

/// @dev Op type of an entry's maximum hourly deposit.
bytes32 constant OP_ADMISSION_CAP_1HR = keccak256("Registry.ADMISSION_CAP_1HR");

/// @dev Op type of an entry's minimum weight.
bytes32 constant OP_MIN_WEIGHT = keccak256("Registry.MIN_WEIGHT");

/// @title AssetConfigFacet
/// @notice The Registry's assets, their listings and their risk parameters: code the Registry
///         delegatecalls, reading and writing the Registry's storage through `RegistryStorage`.
contract AssetConfigFacet is IRegistryFacet, RegistryStorage, CallContextChecker {
    /// @dev Largest funding or borrow rate cap, 11.42% an hour (about 100,000% a year),
    ///      scaled by 100,000,000 per hour.
    uint256 internal constant _RATE_CEILING = 11_420_000;

    /// @notice Validates an asset or risk-parameter operation for the Registry, applies it when
    ///         `applyChange`, and returns the key it is pending under.
    /// @param opType One of this file's op types; the Registry's constants of the same names
    ///        document each one's params.
    /// @param params The op type's parameters.
    /// @param applyChange Whether to store the change.
    /// @return pendingKey The pending key.
    function applyOperation(bytes32 opType, bytes calldata params, bool applyChange)
        external
        onlyProxy
        returns (bytes32 pendingKey)
    {
        if (opType == OP_RISK_PARAMETERS) {
            (uint16 index, Registry.RiskParameters memory parameters) =
                abi.decode(params, (uint16, Registry.RiskParameters));
            _requireAsset(index);
            validateRiskParameters(parameters);
            if (applyChange) riskParameters[index] = parameters;
            return indexKey(opType, index);
        } else if (opType == OP_ADD_NEW_ASSET) {
            return _applyAddNewAsset(opType, params, applyChange);
        } else if (opType == OP_ADD_FUNGIBLE_ASSET_LISTING) {
            Registry.AssetData memory data = abi.decode(params, (Registry.AssetData));
            _requireAssetListing(data);
            if (applyChange) _writeAssetListing(data);
            return _tokenKey(opType, data.chainId, data.index, data.assetAddress);
        } else if (
            opType == OP_ADMISSION_CAP || opType == OP_ADMISSION_CAP_1HR || opType == OP_MIN_WEIGHT
        ) {
            (Registry.ChainId memory chain, uint16 index, bytes32 assetAddress, uint256 value) =
                abi.decode(params, (Registry.ChainId, uint16, bytes32, uint256));
            _requireAsset(index);
            if (applyChange) _writeEntryValue(opType, chain, index, assetAddress, value);
            return _tokenKey(opType, chain, index, assetAddress);
        } else {
            revert GovernanceCore.UnknownOperationType(opType);
        }
    }

    /// @dev Adds `data` as a listing under its asset, or overwrites that listing in full.
    function _writeAssetListing(Registry.AssetData memory data) private {
        Registry.Asset storage reg = assets.registry[data.index];

        uint64 routingId = data.chainId.routingId;
        uint64 vmId = data.chainId.vmId;

        bool isNewListing = reg.data[routingId][vmId][data.assetAddress].assetAddress == bytes32(0);
        reg.data[routingId][vmId][data.assetAddress] = data;

        if (isNewListing) {
            reg.chains.push(data.chainId);
            reg.addresses.push(data.assetAddress);
            assets.totalEntries += 1;
            // Store index + 1 so that 0 means "not found".
            assetIndexLookup[routingId][vmId][data.assetAddress] = uint256(data.index) + 1;
            emit Registry.AssetEntryAdded(data.index, data.chainId, data.assetAddress);
        }
    }

    function _requireAssetListing(Registry.AssetData memory data) private view {
        _requireAsset(data.index);
        if (data.assetAddress == bytes32(0)) revert Registry.ZeroAddress();
        ChainAddress.requireLeftAligned(data.chainId.routingId, data.assetAddress);
        uint256 lookupValue =
            assetIndexLookup[data.chainId.routingId][data.chainId.vmId][data.assetAddress];
        if (lookupValue != 0 && lookupValue != uint256(data.index) + 1) {
            revert Registry.AssetAlreadyRegistered();
        }
    }

    function _requireNewAsset(Registry.ChainId memory chain, bytes32 assetAddress) private view {
        if (assetAddress == bytes32(0)) revert Registry.ZeroAddress();
        ChainAddress.requireLeftAligned(chain.routingId, assetAddress);
        if (assetIndexLookup[chain.routingId][chain.vmId][assetAddress] != 0) {
            revert Registry.AssetAlreadyRegistered();
        }
    }

    function _requireAsset(uint16 index) private view {
        if (index >= assets.count) revert Registry.IndexOutOfBounds();
    }

    function _writeEntryValue(
        bytes32 opType,
        Registry.ChainId memory chain,
        uint16 index,
        bytes32 assetAddress,
        uint256 value
    ) private {
        Registry.AssetData storage entry =
            assets.registry[index].data[chain.routingId][chain.vmId][assetAddress];
        uint256 previous;
        if (opType == OP_ADMISSION_CAP) {
            previous = entry.admissionCap;
            entry.admissionCap = value;
            emit Registry.AdmissionCapChanged(chain, index, previous, value);
        } else if (opType == OP_ADMISSION_CAP_1HR) {
            previous = entry.admissionCap1hr;
            entry.admissionCap1hr = value;
            emit Registry.AdmissionCap1hrChanged(chain, index, previous, value);
        } else {
            previous = entry.minWeight;
            entry.minWeight = value;
            emit Registry.MinWeightChanged(chain, index, previous, value);
        }
    }

    /**
     * @notice Retrieves asset data for a specific asset, chain, and address.
     * @param chainId the chain ID to query.
     * @param index The asset index to query.
     * @param assetAddress The asset address to query.
     * @return The corresponding AssetData struct.
     */
    function getAssetData(Registry.ChainId calldata chainId, uint16 index, bytes32 assetAddress)
        external
        view
        onlyProxy
        returns (Registry.AssetData memory)
    {
        return assets.registry[index].data[chainId.routingId][chainId.vmId][assetAddress];
    }

    /**
     * @notice Returns all registered asset data across all chains.
     * @return An array of AssetData structs.
     * @param start The start index (inclusive).
     * @param end The end index (not-inclusive).
     */
    function getAssets(uint16 start, uint16 end)
        external
        view
        onlyProxy
        returns (Registry.AssetData[] memory)
    {
        uint16 length = Paging.clampPage(start, end, assets.totalEntries);
        Registry.AssetData[] memory result = new Registry.AssetData[](length);

        uint256 r = 0;
        uint256 resIdx = 0;

        for (uint16 i = 0; i < assets.count && resIdx < length; ++i) {
            Registry.Asset storage asset = assets.registry[i];
            uint256 chainsLen = asset.chains.length;

            for (uint256 c = 0; c < chainsLen && resIdx < length; ++c) {
                if (r >= start && r < end) {
                    Registry.ChainId storage chain = asset.chains[c];
                    result[resIdx++] = asset.data[chain.routingId][chain.vmId][asset.addresses[c]];
                }

                ++r;
            }
        }

        return result;
    }

    /**
     * @notice Returns the asset index for a given chain and address.
     * @param chainId The chain ID to search.
     * @param assetAddress The asset address (as bytes32).
     * @return The index of the asset, or `ASSET_NOT_FOUND` if not found.
     */
    function getAssetIndex(Registry.ChainId calldata chainId, bytes32 assetAddress)
        external
        view
        onlyProxy
        returns (uint32)
    {
        uint256 stored = assetIndexLookup[chainId.routingId][chainId.vmId][assetAddress];
        if (stored == 0) {
            return ASSET_NOT_FOUND;
        }
        // forge-lint: disable-next-line(unsafe-typecast)
        return uint32(stored - 1);
    }

    /**
     * @notice Reverts unless `params` are valid risk parameters.
     * @param params The parameters to validate.
     */
    function validateRiskParameters(Registry.RiskParameters memory params) public pure {
        if (params.collateralFactor > 1e2) revert Registry.InvalidCollateralFactor();
        if (params.liabilityFactor > 1e2) revert Registry.InvalidLiabilityFactor();
        if (params.maxUtilization > 1e18) revert Registry.InvalidUtilizationCap();
        if (params.maxFundingRate > _RATE_CEILING) revert Registry.InvalidMaxFundingRate();
        if (params.maxBorrowRate > _RATE_CEILING) revert Registry.InvalidMaxBorrowRate();

        if (params.skewModifier > 1e6) revert Registry.InvalidSkewModifier();
        if (params.skewCliff > 1e6) revert Registry.InvalidSkewCliff();
        if (params.baseFundingRate > 1e8 || params.baseFundingRate < -1e8) {
            revert Registry.InvalidBaseFundingRate();
        }
        if (params.premiumClamp > 1e6) revert Registry.InvalidPremiumClamp();

        uint256 bufferMultiple = params.bufferMultiple;
        if (bufferMultiple < 1e6 || bufferMultiple > 2e6) revert Registry.InvalidBufferMultiple();

        if (!SeriesValidation.validateStartAtZeroIsAlwaysBelowOneAndIncreases(params.interestKinks))
        {
            revert Registry.InvalidInterestKinks();
        }
        if (!SeriesValidation.validateLastIsOne(params.interestKinks)) {
            revert Registry.InvalidInterestKinks();
        }
        if (!SeriesValidation.validateStartAtZeroIsAlwaysBelowOneAndIncreases(
                params.usdInterestKinks
            )) {
            revert Registry.InvalidUSDInterestKinks();
        }
        if (!SeriesValidation.validateLastIsOne(params.usdInterestKinks)) {
            revert Registry.InvalidUSDInterestKinks();
        }

        if (
            params.interestKinks.length != params.kinkInterestRates.length
                || !SeriesValidation.validateIncreases(params.kinkInterestRates)
                || params.kinkInterestRates[params.kinkInterestRates.length - 1] > 1e8
        ) {
            revert Registry.InvalidRateInterestKinks();
        }
        if (
            params.usdInterestKinks.length != params.usdKinkInterestRates.length
                || !SeriesValidation.validateIncreases(params.usdKinkInterestRates)
                || params.usdKinkInterestRates[params.usdKinkInterestRates.length - 1] > 1e8
        ) {
            revert Registry.InvalidUSDRateInterestKinks();
        }

        if (params.initialMarginClamps.length != params.initialMarginFactors.length) {
            revert Registry.InvalidInitialMarginsConfiguration();
        }
        if (!SeriesValidation.validateStartAtZeroIsAlwaysBelowOneAndIncreases(
                params.initialMarginClamps
            )) {
            revert Registry.InvalidInitialMarginsClamps();
        }
        if (!validateIMFactors(params.initialMarginFactors)) {
            revert Registry.InvalidInitialMarginsFactors();
        }
    }

    /**
     * @notice IM factors must always decreases and be < 1 (1_000_000)
     */
    function validateIMFactors(uint256[] memory xs) private pure returns (bool) {
        uint256 len = xs.length;
        uint256 prev = 999_999;

        for (uint256 i; i < len; ++i) {
            uint256 cur = xs[i];
            if (cur > prev) return false;
            prev = cur;
        }

        return true;
    }

    /**
     * @notice Returns the full list of risk parameters for all registered assets.
     * @return An array of RiskParameters.
     * @param start The start index (inclusive).
     * @param end The end index (not inclusive).
     */
    function getRiskParameters(uint16 start, uint16 end)
        external
        view
        onlyProxy
        returns (Registry.RiskParameters[] memory)
    {
        uint16 length = Paging.clampPage(start, end, assets.count);
        Registry.RiskParameters[] memory result = new Registry.RiskParameters[](length);

        for (uint16 i = 0; i < length; ++i) {
            result[i] = riskParameters[start + i];
        }

        return result;
    }

    function _tokenKey(
        bytes32 opType,
        Registry.ChainId memory chain,
        uint16 index,
        bytes32 assetAddress
    ) private pure returns (bytes32) {
        return keccak256(abi.encode(opType, chain.routingId, chain.vmId, index, assetAddress));
    }

    /// @dev Validates a new asset's listings and, when `applyChange`, registers them all at their
    ///      signed index, which must be the next one.
    function _applyAddNewAsset(bytes32 opType, bytes calldata params, bool applyChange)
        private
        returns (bytes32)
    {
        Registry.AssetData[] memory listings = abi.decode(params, (Registry.AssetData[]));
        uint256 listingCount = listings.length;
        if (listingCount == 0 || listingCount > MAX_NEW_ASSET_LISTINGS) {
            revert Registry.NewAssetListingCountOutOfRange(listingCount);
        }
        uint16 index = listings[0].index;
        for (uint256 listingIndex; listingIndex < listingCount; ++listingIndex) {
            Registry.AssetData memory data = listings[listingIndex];
            if (data.index != index) {
                revert Registry.NewAssetListingIndexMismatch(data.index, index);
            }
            _requireNewAsset(data.chainId, data.assetAddress);
            if (applyChange) {
                _writeAssetListing(data);
            } else {
                _requireNoEarlierDuplicate(listings, listingIndex);
            }
        }
        uint256 next = assets.count;
        if (applyChange) {
            if (index != next) revert Registry.NewAssetIndexNotNext(index, next);
            assets.count = next + 1;
        } else if (index < next) {
            revert Registry.NewAssetIndexNotNext(index, next);
        }
        return keccak256(abi.encode(opType, index));
    }

    /// @dev Reverts `DuplicateNewAssetListing` if a listing before `listingIndex` is the same token
    ///      on the same chain.
    function _requireNoEarlierDuplicate(Registry.AssetData[] memory listings, uint256 listingIndex)
        private
        pure
    {
        Registry.AssetData memory data = listings[listingIndex];
        for (uint256 earlierIndex; earlierIndex < listingIndex; ++earlierIndex) {
            Registry.AssetData memory earlier = listings[earlierIndex];
            if (
                earlier.assetAddress == data.assetAddress
                    && earlier.chainId.routingId == data.chainId.routingId
                    && earlier.chainId.vmId == data.chainId.vmId
            ) revert Registry.DuplicateNewAssetListing();
        }
    }
}

