src/interfaces/IDepositVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

import {GovernanceSnapshot} from "../types/GovernanceSnapshot.sol";

import {CommitteeMember} from "../types/GovernanceSnapshot.sol";

interface IDepositVault {
    type OperationStatus is uint8;

    struct DelayBounds {
        uint64 lowerSeconds;
        uint64 upperSeconds;
        bool configured;
    }

    struct Operation {
        bytes32 opType;
        bytes32 key;
        bytes32 paramsHash;
        uint64 lowerEtaSeconds;
        uint64 upperEtaSeconds;
        OperationStatus status;
    }

    type SettlementMode is uint8;

    struct Settlement {
        address tokenOut;
        uint256 amountOut;
        address tokenIn;
        uint256 amountIn;
        SettlementMode mode;
        bytes32 user;
        uint64 account;
        uint64 nonce;
        uint256 validUntil;
    }

    struct SignedSettlement {
        Settlement settlement;
        bytes clearingEngineSignature;
    }

    struct SignerConfig {
        bytes32 key;
        uint8 keyType;
        uint8 keyPrefix;
        uint32 weight;
        uint64 expiresAtNs;
        uint64 maxSigningWindowNs;
    }

    struct Withdrawal {
        address tokenAddress;
        uint256 amount;
        uint64 nonce;
    }

    error AdministratorIndexOutOfBounds(uint256 index);
    error ApprovalExpired(uint256 deadline);
    error BoundsAlreadyInitialized(bytes32 opType);
    error DecimalsCallFailed();
    error DepositorNotApproved();
    error DuplicateSnapshotMember(address account);
    error EtaOverflow();
    error Expired();
    error InsufficientAmountFromExecutor(uint256 actual, uint256 required);
    error InsufficientCallbackReturnForSettlement(
        uint256 settlementIndex, uint256 actual, uint256 required
    );
    error InsufficientSignatures(uint256 supplied, uint256 required);
    error InvalidBounds(uint64 lowerSeconds, uint64 upperSeconds);
    error InvalidInitialization();
    error InvalidNonce(uint256 expected, uint256 given);
    error InvalidSignature();
    error InvalidSnapshotCommitteeThreshold(uint256 threshold, uint256 memberCount);
    error InvalidSnapshotCouncilThreshold(uint256 threshold, uint256 councilCount);
    error InvalidSnapshotWithdrawalQuorum(uint256 quorum, uint256 keyCount);
    error InvalidThreshold();
    error MissedQuorum(uint256 provided, uint256 required);
    error NonceTooFar(uint256 nonce, uint256 lastAccepted);
    error NormalizationOverflow();
    error NormalizationRoundsToZero();
    error NotAdmin();
    error NotCredentialManager();
    error NotExecutor();
    error NotInitializing();
    error NotMember(address signer);
    error NotPending(bytes32 opId);
    error NotReady(uint64 etaSeconds);
    error NotSettlementAdmin();
    error ParametersMismatch(bytes32 opId);
    error PayloadMismatch();
    error Reentrancy();
    error ReservedOperationType();
    error SettlerNotApproved();
    error SignatureCountMismatch();
    error SignatureNotFromSigner(address signer);
    error SignersNotSortedOrUnique();
    error StaleNonce(uint256 nonce, uint256 lastAccepted);
    error TokenAmountMismatch(uint256 expected, uint256 actual);
    error TokenBalanceQueryFailed();
    error UnauthorizedCallContext();
    error UniverseAlreadySet();
    error UniverseUnset();
    error UnknownOperationType(bytes32 opType);
    error UpgradeFailed();
    error UpgradeNotAuthorized();
    error WrongOperationKey(bytes32 opId);
    error WrongOperationType(bytes32 opId);
    error ZeroAddress();
    error ZeroAmount();
    error ZeroSnapshotMember();
    error ZeroSnapshotVersion();
    error ZeroUniverse();
    error ZeroWithdrawalQuorum();

    event DelayBoundsChanged(
        bytes32 indexed targetOpType, uint64 lowerSeconds, uint64 upperSeconds
    );
    event Deposited(
        bytes32 indexed user,
        uint256 indexed nonce,
        address indexed tokenAddress,
        uint256 amount,
        uint64 eventCount,
        bytes24 eventHash
    );
    event DepositedWithConfig(
        bytes32 indexed user,
        uint256 indexed nonce,
        address indexed tokenAddress,
        uint256 amount,
        uint32 masterWeight,
        uint32 lowThreshold,
        uint32 mediumThreshold,
        uint32 highThreshold,
        SignerConfig[] signers,
        bytes masterConfigSignature,
        uint64 eventCount,
        bytes24 eventHash
    );
    event GovernanceSnapshotSet(
        uint64 indexed version, bytes32 indexed stateHash, GovernanceSnapshot snapshot
    );
    event Initialized(uint64 version);
    event OperationCanceled(bytes32 indexed opId, bytes32 indexed opType);
    event OperationExecuted(bytes32 indexed opId, bytes32 indexed opType);
    event OperationScheduled(
        bytes32 indexed opId,
        bytes32 indexed opType,
        bytes32 indexed key,
        uint64 lowerEtaSeconds,
        uint64 upperEtaSeconds,
        bytes parameters,
        address[] signers
    );
    event OperationVetoed(bytes32 indexed opId, bytes32 indexed opType);
    event Settled(
        bytes32 indexed user,
        uint64 indexed account,
        uint256 indexed nonce,
        address tokenOut,
        uint256 amountOut,
        address tokenIn,
        uint256 amountIn,
        SettlementMode mode,
        bytes32 settler,
        uint64 eventCount,
        bytes24 eventHash
    );
    event SettlementAdminChanged(address oldSettlementAdmin, address newSettlementAdmin);
    event Upgraded(address indexed implementation);
    event WithdrawalQuorumChanged(uint256 previous, uint256 current);
    event Withdrew(
        bytes32 indexed user,
        uint256 indexed nonce,
        address tokenAddress,
        uint256 amount,
        uint64 eventCount,
        bytes24 eventHash
    );

    function DEPOSITED_KIND() external view returns (uint8);
    function DEPOSITED_WITH_CONFIG_KIND() external view returns (uint8);
    function SETTLED_KIND() external view returns (uint8);
    function SETTLEMENT_ADMIN_KEY() external view returns (bytes32);
    function SETTLEMENT_TYPEHASH() external view returns (bytes32);
    function WITHDREW_KIND() external view returns (uint8);
    function addSettlerExecutor(bytes32 settler, address executor) external;
    function administrators(uint256 index) external view returns (address);
    function approvedSettlers(uint256) external view returns (bytes32);
    function canDeposit(address) external view returns (bool);
    function committeeThreshold() external view returns (uint256);
    function credentialManager() external view returns (address);
    function deposit(
        bytes32 user,
        address tokenAddress,
        uint256 amount,
        uint32 masterWeight,
        uint32 lowThreshold,
        uint32 mediumThreshold,
        uint32 highThreshold,
        SignerConfig[] memory signers,
        bytes memory masterConfigSignature
    ) external;
    function deposit(bytes32 user, address tokenAddress, uint256 amount) external;
    function depositCounts(bytes32) external view returns (uint64);
    function domainSeparator() external view returns (bytes32);
    function eventCount() external view returns (uint64);
    function eventHash() external view returns (bytes24);
    function eventHead() external view returns (uint64 count, bytes24 hash);
    function executeAtomicSettlement(
        Settlement memory order,
        bytes32 settler,
        bytes memory data,
        bytes memory signature
    ) external;
    function executeBatchSettlements(
        SignedSettlement[] memory requests,
        bytes[] memory data,
        bytes32 settler
    ) external;
    function executeSettlementAdminChange(
        bytes32 opId,
        address newSettlementAdmin,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function executeUpgrade(
        bytes32 opId,
        address implementation,
        bytes memory migrationData,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function executeUpgradeDelayChange(
        bytes32 opId,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function getApprovedSettlers() external view returns (bytes32[] memory);
    function getGovernanceSnapshot() external view returns (GovernanceSnapshot memory);
    function initialize(
        address _settlementAdmin,
        address _credentialManager,
        bytes32 _universeId,
        uint64 _upgradeDelaySeconds,
        GovernanceSnapshot memory genesis
    ) external;
    function isAdministrator(address account) external view returns (bool);
    function isOperator(address account) external view returns (bool);
    function isSecurityCouncil(address account) external view returns (bool);
    function lastSignatureUse() external view returns (uint256);
    function pendingUpgradeOperations()
        external
        view
        returns (bytes32 upgradeId, bytes32 delayChangeId);
    function proxiableUUID() external view returns (bytes32);
    function removeSettler(bytes32 settler) external;
    function scheduleSettlementAdminChange(
        address newSettlementAdmin,
        uint256 nonce,
        uint256 deadline,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32);
    function scheduleUpgrade(
        address implementation,
        bytes32 migrationDataHash,
        uint256 nonce,
        uint256 deadline,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32);
    function scheduleUpgradeDelayChange(
        uint64 lowerSeconds,
        uint64 upperSeconds,
        uint256 nonce,
        uint256 deadline,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32);
    function securityCouncilThreshold() external view returns (uint256);
    function setDepositorStatus(address depositor, bool allowed) external;
    function setGovernanceSnapshot(GovernanceSnapshot memory snapshot) external;
    function settlementAdmin() external view returns (address);
    function settlementCounts(bytes32, uint64) external view returns (uint64);
    function upgradeDelayBounds() external view returns (DelayBounds memory);
    function upgradeDomainSeparator() external view returns (bytes32);
    function upgradeGovernanceNonces()
        external
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce);
    function upgradeOpType() external view returns (bytes32);
    function upgradeOperation(bytes32 opId) external view returns (Operation memory);
    function upgradeToAndCall(address newImplementation, bytes memory data) external payable;
    function vetoUpgradeOperation(
        bytes32 opId,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function withdraw(
        Withdrawal memory withdrawal,
        bytes32 user,
        address target,
        uint256 validUntil,
        bytes32 epochHash,
        bytes[] memory signatures
    ) external;
    function withdrawalCounts(bytes32) external view returns (uint64);
    function withdrawalQuorum() external view returns (uint256);
}

src/interfaces/IGovernanceAuthority.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice What a contract governed alongside the CredentialManager reads from it: its governance
///         domain, its role, the operator committee and the security council.
interface IGovernanceAuthority {
    /// @notice Whether a manager is the universe's canonical manager or the manager of another L1.
    enum ManagerRole {
        /// @dev The canonical manager.
        Canonical,
        /// @dev The manager of another L1.
        Local
    }

    /// @notice EIP-712 domain separator the manager's council signatures are made under.
    /// @return The domain separator.
    function domainSeparator() external view returns (bytes32);

    /// @notice The manager's role.
    /// @return The role.
    function managerRole() external view returns (ManagerRole);

    /// @notice Whether an address is an operator, a member of the committee.
    /// @param account The address checked.
    /// @return Whether `account` is an operator.
    function isOperator(address account) external view returns (bool);

    /// @notice Committee signatures a committee action needs.
    /// @return The committee threshold.
    function committeeThreshold() external view returns (uint256);

    /// @notice Whether an address is a security council member.
    /// @param account The address checked.
    /// @return Whether `account` is a security council member.
    function isSecurityCouncil(address account) external view returns (bool);

    /// @notice Council signatures an early execute or a veto needs.
    /// @return The security council threshold.
    function securityCouncilThreshold() external view returns (uint256);
}

