// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

interface IMeasurementProfileRegistry {
    type OperationStatus is uint8;

    struct DelayBounds {
        uint64 lowerSeconds;
        uint64 upperSeconds;
        bool configured;
    }

    struct Operation {
        bytes32 opType;
        bytes32 key;
        bytes32 paramsHash;
        uint64 lowerEtaSeconds;
        uint64 upperEtaSeconds;
        OperationStatus status;
    }

    struct DelayPair {
        uint64 lowerSeconds;
        uint64 upperSeconds;
    }

    struct Profile {
        bytes32 mrtd;
        bytes32 rtmr0;
        bytes32 rtmr1;
        bytes32 rtmr2;
        bytes32 rtmr3;
    }

    /// @notice Thrown when a schedule approval is submitted after its deadline.
    /// @param deadline The approval's deadline.
    error ApprovalExpired(uint256 deadline);
    /// @notice Thrown when an op type's delay bounds are initialized a second time.
    /// @param opType The already configured op type.
    error BoundsAlreadyInitialized(bytes32 opType);
    /// @notice Thrown when the CredentialManager's approvals are signed under another domain.
    error DomainMismatch();
    /// @notice Thrown when an eta does not fit in 64 bits.
    error EtaOverflow();
    /// @notice Thrown when fewer signatures than the threshold are supplied.
    /// @param supplied The number of signers supplied.
    /// @param required The threshold.
    error InsufficientSignatures(uint256 supplied, uint256 required);
    /// @notice Thrown when a bound exceeds `MAX_DELAY_SECONDS` or the upper is below the lower.
    /// @param lowerSeconds The rejected lower bound.
    /// @param upperSeconds The rejected upper bound.
    error InvalidBounds(uint64 lowerSeconds, uint64 upperSeconds);
    /// @dev The contract is already initialized.
    error InvalidInitialization();
    /// @notice Thrown when an authority's threshold is zero.
    error InvalidThreshold();
    /// @notice Thrown when a schedule's nonce moves more than `MAX_NONCE_STEP` past the highest one
    ///     accepted.
    /// @param nonce The rejected nonce.
    /// @param lastAccepted The highest nonce accepted so far.
    error NonceTooFar(uint256 nonce, uint256 lastAccepted);
    /// @dev The contract is not initializing.
    error NotInitializing();
    /// @notice Thrown when a signer is not in the authority's member set.
    /// @param signer The signer that is not a member.
    error NotMember(address signer);
    /// @notice Thrown when an operation is not pending: unknown, executed, superseded or vetoed.
    /// @param opId The operation's ID.
    error NotPending(bytes32 opId);
    /// @notice Thrown when an operation is executed before the eta its path requires.
    /// @param etaSeconds The eta that has not passed yet.
    error NotReady(uint64 etaSeconds);
    /// @notice Thrown when execute params do not hash to the scheduled params hash.
    /// @param opId The operation's ID.
    error ParametersMismatch(bytes32 opId);
    /// @notice Thrown when `OP_SET_DELAY_BOUNDS` is used outside the delay-change entry points.
    error ReservedOperationType();
    /// @notice Thrown when the signer and signature arrays differ in length.
    error SignatureCountMismatch();
    /// @notice Thrown when a signature does not verify for its signer over the signed digest.
    /// @param signer The signer whose signature failed.
    error SignatureNotFromSigner(address signer);
    /// @notice Thrown when signers are not in strictly ascending address order.
    error SignersNotSortedOrUnique();
    /// @notice Thrown when a schedule's nonce is not above the highest one accepted.
    /// @param nonce The rejected nonce.
    /// @param lastAccepted The highest nonce accepted so far.
    error StaleNonce(uint256 nonce, uint256 lastAccepted);
    /// @notice Thrown when a kind is given more than `MAX_PROFILES_PER_KIND` profiles.
    /// @param count The rejected number of profiles.
    error TooManyProfiles(uint256 count);
    /// @dev The call is from an unauthorized call context.
    error UnauthorizedCallContext();
    /// @notice Thrown when a host's universe ID is set a second time.
    error UniverseAlreadySet();
    /// @notice Thrown when a digest is computed before the host's universe ID is set.
    error UniverseUnset();
    /// @notice Thrown when a kind ID is not below `KIND_COUNT`.
    /// @param kind The rejected kind.
    error UnknownKind(uint32 kind);
    /// @notice Thrown when an op type has no initialized bounds or the entry point rejects it.
    /// @param opType The rejected op type.
    error UnknownOperationType(bytes32 opType);
    /// @dev The upgrade failed.
    error UpgradeFailed();
    /// @notice Thrown when `upgradeToAndCall` is called outside `executeUpgrade`.
    error UpgradeNotAuthorized();
    /// @notice Thrown when an operation is executed under another key.
    /// @param opId The operation's ID.
    error WrongOperationKey(bytes32 opId);
    /// @notice Thrown when an operation is executed through another op type's entry point.
    /// @param opId The operation's ID.
    error WrongOperationType(bytes32 opId);
    /// @notice Thrown when a required address is zero.
    error ZeroAddress();
    /// @notice Thrown when a profile has a zero MRTD.
    /// @param index The profile's position in the list.
    error ZeroMrtd(uint256 index);
    /// @notice Thrown when a universe ID is zero.
    error ZeroUniverse();

    /// @notice Emitted when an op type's delay bounds are set.
    /// @param targetOpType The op type whose bounds are set.
    /// @param lowerSeconds The new lower bound.
    /// @param upperSeconds The new upper bound.
    event DelayBoundsChanged(
        bytes32 indexed targetOpType, uint64 lowerSeconds, uint64 upperSeconds
    );
    /// @dev Triggered when the contract has been initialized.
    event Initialized(uint64 version);
    /// @notice Emitted when a new schedule under the same key supersedes a pending operation.
    /// @param opId The superseded operation's ID.
    /// @param opType The superseded operation's type.
    event OperationCanceled(bytes32 indexed opId, bytes32 indexed opType);
    /// @notice Emitted when a pending operation executes.
    /// @param opId The executed operation's ID.
    /// @param opType The executed operation's type.
    event OperationExecuted(bytes32 indexed opId, bytes32 indexed opType);
    /// @notice Emitted when an operation is scheduled.
    /// @param opId The new operation's ID.
    /// @param opType The operation's type.
    /// @param key The slot the operation is pending under.
    /// @param lowerEtaSeconds Earliest timestamp at which a council-approved execute succeeds.
    /// @param upperEtaSeconds Earliest timestamp at which anyone can execute.
    /// @param parameters The full ABI-encoded params.
    /// @param signers The approving members; empty for a self-authorized schedule.
    event OperationScheduled(
        bytes32 indexed opId,
        bytes32 indexed opType,
        bytes32 indexed key,
        uint64 lowerEtaSeconds,
        uint64 upperEtaSeconds,
        bytes parameters,
        address[] signers
    );
    /// @notice Emitted when the council vetoes a pending operation.
    /// @param opId The vetoed operation's ID.
    /// @param opType The vetoed operation's type.
    event OperationVetoed(bytes32 indexed opId, bytes32 indexed opType);
    /// @notice Emitted when a kind's profiles are set.
    /// @param kind The service kind.
    /// @param profiles The kind's approved profiles, replacing the earlier ones.
    event ProfilesSet(uint32 indexed kind, Profile[] profiles);
    /// @dev Emitted when the proxy's implementation is upgraded.
    event Upgraded(address indexed implementation);

    /// @notice Number of service kinds.
    function KIND_COUNT() external view returns (uint32);
    /// @notice Most profiles a kind may have approved at once.
    function MAX_PROFILES_PER_KIND() external view returns (uint256);
    /// @notice Sets a kind's profiles.
    /// @dev Portable. Op type and key `profileOpType(kind)`, hashed from this and the kind. Params
    ///     `abi.encode(uint32 kind, Profile[] profiles)`.
    function OP_SET_PROFILE() external view returns (bytes32);
    /// @notice Upgrades the implementation, scheduled by `scheduleUpgrade`.
    /// @dev Deployment-specific. Params `abi.encode(address implementation, bytes32 codeHash,
    ///     bytes32 migrationDataHash)`. Key `opType`.
    function OP_UPGRADE() external view returns (bytes32);
    /// @notice The clearing engine's approved profiles; empty when none is set.
    /// @return The profiles.
    function clearingEngineProfiles() external view returns (Profile[] memory);
    /// @notice The CredentialManager whose committee and security council govern here.
    function credentialManager() external view returns (address);
    /// @notice An op type's delay bounds.
    /// @param opType The op type's portable ID.
    /// @return The bounds.
    function delayBounds(bytes32 opType) external view returns (DelayBounds memory);
    /// @notice The ID this deployment signs, keys and bounds an op type under.
    /// @param opType The op type's portable ID.
    /// @return The deployment op type.
    function deploymentOpType(bytes32 opType) external view returns (bytes32);
    /// @notice [EIP-712](https://eips.ethereum.org/EIPS/eip-712) domain separator committee and
    ///     council approvals are signed under.
    /// @return The domain separator.
    function domainSeparator() external view returns (bytes32);
    /// @notice Executes a scheduled delay change.
    /// @param opId The operation's ID.
    /// @param targetOpType The scheduled op type.
    /// @param lowerSeconds The scheduled lower bound.
    /// @param upperSeconds The scheduled upper bound.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeDelayChange(
        bytes32 opId,
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    /// @notice Executes a scheduled list of profiles.
    /// @param opId The operation's ID.
    /// @param kind The scheduled kind.
    /// @param newProfiles The scheduled profiles.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeSetProfiles(
        bytes32 opId,
        uint32 kind,
        Profile[] memory newProfiles,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    /// @notice Executes a scheduled upgrade and runs its migration call.
    /// @param opId The operation's ID.
    /// @param implementation The scheduled implementation, with its scheduled code hash.
    /// @param migrationData The call whose hash was scheduled; empty skips the call.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeUpgrade(
        bytes32 opId,
        address implementation,
        bytes memory migrationData,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    /// @notice The highest schedule nonce accepted and the council nonce signed next.
    /// @return lastScheduleNonce The highest schedule nonce accepted; sign a schedule above it.
    /// @return nextCouncilNonce The nonce the next council execute or veto signs.
    function governanceNonces()
        external
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce);
    /// @notice Sets the CredentialManager, the universe and every op type's delay bounds, once.
    /// @param manager The CredentialManager whose committee and security council govern here.
    /// @param universeId The universe whose approvals the CredentialManager accepts.
    /// @param kindBounds Each kind's delay pair, by kind ID.
    /// @param upgradeBounds The delay pair of `OP_UPGRADE`.
    function initialize(
        address manager,
        bytes32 universeId,
        DelayPair[10] memory kindBounds,
        DelayPair memory upgradeBounds
    ) external;
    /// @notice An operation by ID.
    /// @param opId The operation's ID.
    /// @return The operation.
    function operation(bytes32 opId) external view returns (Operation memory);
    /// @notice ID of the operation pending under `key`, or zero.
    /// @param key The key the operation is scheduled under.
    /// @return The operation's ID.
    function pendingId(bytes32 key) external view returns (bytes32);
    /// @notice The op type and key a kind's profile is scheduled under.
    /// @param kind The service kind.
    /// @return The op type.
    function profileOpType(uint32 kind) external pure returns (bytes32);
    /// @notice A kind's approved profiles; empty when none is set.
    /// @param kind The service kind.
    /// @return The kind's profiles.
    function profiles(uint32 kind) external view returns (Profile[] memory);
    /// @dev Returns the storage slot used by the implementation, as specified in
    ///     [ERC1822](https://eips.ethereum.org/EIPS/eip-1822). Note: The `notDelegated` modifier
    ///     prevents accidental upgrades to an implementation that is a proxy contract.
    function proxiableUUID() external view returns (bytes32);
    /// @notice Schedules a change of an op type's delay bounds, waiting its current bounds.
    /// @param targetOpType `profileOpType(kind)` or `OP_UPGRADE`.
    /// @param lowerSeconds The new lower bound.
    /// @param upperSeconds The new upper bound.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadlineSeconds Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return opId The operation's ID.
    function scheduleDelayChange(
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        uint256 nonce,
        uint256 deadlineSeconds,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32 opId);
    /// @notice Schedules a kind's profiles, superseding the list pending for that kind. On execute
    ///     the list replaces every profile the kind had.
    /// @param kind The service kind.
    /// @param newProfiles The approved profiles, at most `MAX_PROFILES_PER_KIND`, each with a
    ///     non-zero MRTD; an empty list leaves the kind with no profile.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadlineSeconds Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return opId The operation's ID.
    function scheduleSetProfiles(
        uint32 kind,
        Profile[] memory newProfiles,
        uint256 nonce,
        uint256 deadlineSeconds,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32 opId);
    /// @notice Schedules an upgrade pinned to the implementation's current code hash.
    /// @param implementation The new implementation, a UUPS implementation with code.
    /// @param migrationDataHash Hash of the call made on the new implementation after the switch.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadline Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return The operation's ID.
    function scheduleUpgrade(
        address implementation,
        bytes32 migrationDataHash,
        uint256 nonce,
        uint256 deadline,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32);
    /// @notice The op type upgrade approvals are signed and keyed under, bound to this chain and
    ///     this contract's address. Params `abi.encode(address implementation, bytes32 codeHash,
    ///     bytes32 migrationDataHash)`.
    /// @return The deployment op type of the upgrade.
    function upgradeOpType() external view returns (bytes32);
    /// @dev Upgrades the proxy's implementation to `newImplementation`. Emits a {Upgraded} event.
    ///     Note: Passing in empty `data` skips the delegatecall to `newImplementation`.
    function upgradeToAndCall(address newImplementation, bytes memory data) external payable;
    /// @notice Cancels a pending operation with council approval.
    /// @param opId The operation's ID.
    /// @param councilSigners Council members in strictly ascending order.
    /// @param councilSignatures Their signatures over the veto digest.
    function vetoOperation(
        bytes32 opId,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
}

src/interfaces/IRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

interface IRegistry {
    type OperationStatus is uint8;

    struct DelayBounds {
        uint64 lowerSeconds;
        uint64 upperSeconds;
        bool configured;
    }

    struct Operation {
        bytes32 opType;
        bytes32 key;
        bytes32 paramsHash;
        uint64 lowerEtaSeconds;
        uint64 upperEtaSeconds;
        OperationStatus status;
    }

    struct AssetData {
        uint16 index;
        bytes32 assetAddress;
        ChainId chainId;
        uint256 admissionCap;
        uint256 admissionCap1hr;
        uint256 minWeight;
    }

    struct ChainId {
        uint64 routingId;
        uint64 vmId;
    }

    struct OracleConfig {
        OracleSourceConfig[] sources;
        uint8 minSources;
        uint8 priceDecimals;
        uint32 maxDeviationBps;
        uint64 canonicalStalenessSecs;
    }

    struct OracleSourceConfig {
        uint8 sourceKind;
        bytes32 feedId;
        bool active;
        OracleTlsIdentity[] tlsIdentities;
        ChainId chainId;
        uint64 unitsPerContract;
        uint8 validityKind;
        uint64 validitySecs;
        uint64 validityGraceSecs;
    }

    struct OracleTlsIdentity {
        uint8 kind;
        bytes32 identity;
    }

    struct RedemptionDelayParameters {
        uint256 minDelay;
        uint256 maxDelay;
        uint256[] delayClamps;
        uint256[] delayValues;
        uint256 capFloor;
    }

    struct RepresentationConfig {
        bytes32 providerContract;
        uint64 staleAfterSecs;
        uint32 maxRateJumpBps;
        uint8 sourceKind;
    }

    struct RepresentationEntry {
        ChainId chain;
        bytes32 token;
        RepresentationConfig config;
    }

    struct RiskParameters {
        uint8 collateralFactor;
        uint8 liabilityFactor;
        uint256 maxCollateral;
        uint256 maxOpenInterest;
        uint256 maxSpotOpenInterest;
        uint256 maxUtilization;
        bool isolatedOnly;
        uint256[] interestKinks;
        uint256[] kinkInterestRates;
        uint256[] usdInterestKinks;
        uint256[] usdKinkInterestRates;
        uint256 skewModifier;
        uint256 skewCliff;
        int256 baseFundingRate;
        uint256 premiumClamp;
        uint256[] initialMarginClamps;
        uint256[] initialMarginFactors;
        uint256 maxFundingRate;
        uint256 maxBorrowRate;
        uint256 bufferMultiple;
        uint256 minSubAccountBalance;
        uint256 maxAdl;
    }

    error AddressNotLeftAligned(bytes32 chainAddress);
    error ApprovalExpired(uint256 deadline);
    error AssetAlreadyRegistered();
    error BoundsAlreadyInitialized(bytes32 opType);
    error DomainMismatch();
    error DuplicateNewAssetListing();
    error EtaOverflow();
    error IndexOutOfBounds();
    error InsufficientSignatures(uint256 supplied, uint256 required);
    error InvalidBaseFundingRate();
    error InvalidBounds(uint64 lowerSeconds, uint64 upperSeconds);
    error InvalidBufferMultiple();
    error InvalidCollateralFactor();
    error InvalidInitialMarginsClamps();
    error InvalidInitialMarginsConfiguration();
    error InvalidInitialMarginsFactors();
    error InvalidInitialization();
    error InvalidInterestKinks();
    error InvalidLiabilityFactor();
    error InvalidMaxBorrowRate();
    error InvalidMaxFundingRate();
    error InvalidOracleConfig();
    error InvalidPremiumClamp();
    error InvalidRateInterestKinks();
    error InvalidRedemptionDelayBounds();
    error InvalidRedemptionDelayCapFloor();
    error InvalidRedemptionDelayClamps();
    error InvalidRedemptionDelayConfiguration();
    error InvalidRedemptionDelayValues();
    error InvalidRepresentationConfig();
    error InvalidRiskCouncil();
    error InvalidSkewCliff();
    error InvalidSkewModifier();
    error InvalidThreshold();
    error InvalidUSDInterestKinks();
    error InvalidUSDRateInterestKinks();
    error InvalidUtilizationCap();
    error NewAssetIndexNotNext(uint16 index, uint256 next);
    error NewAssetListingCountOutOfRange(uint256 count);
    error NewAssetListingIndexMismatch(uint16 index, uint16 expected);
    error NonceTooFar(uint256 nonce, uint256 lastAccepted);
    error NotCanonicalManager();
    error NotInitializing();
    error NotMember(address signer);
    error NotPending(bytes32 opId);
    error NotReady(uint64 etaSeconds);
    error ParametersMismatch(bytes32 opId);
    error RedemptionDelayValueOutOfBounds();
    error RepresentationNotConfigured();
    error RepresentationTokenNotRegistered();
    error ReservedOperationType();
    error SignatureCountMismatch();
    error SignatureNotFromSigner(address signer);
    error SignersNotSortedOrUnique();
    error StaleNonce(uint256 nonce, uint256 lastAccepted);
    error UnauthorizedCallContext();
    error UniverseAlreadySet();
    error UniverseUnset();
    error UnknownOperationType(bytes32 opType);
    error UpgradeFailed();
    error UpgradeNotAuthorized();
    error WrongOperationKey(bytes32 opId);
    error WrongOperationType(bytes32 opId);
    error ZeroAddress();
    error ZeroUniverse();

    event AdmissionCap1hrChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);
    event AdmissionCapChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);
    event AssetEntryAdded(uint16 indexed index, ChainId chainId, bytes32 assetAddress);
    event DelayBoundsChanged(
        bytes32 indexed targetOpType, uint64 lowerSeconds, uint64 upperSeconds
    );
    event Initialized(uint64 version);
    event MinWeightChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);
    event OperationCanceled(bytes32 indexed opId, bytes32 indexed opType);
    event OperationExecuted(bytes32 indexed opId, bytes32 indexed opType);
    event OperationScheduled(
        bytes32 indexed opId,
        bytes32 indexed opType,
        bytes32 indexed key,
        uint64 lowerEtaSeconds,
        uint64 upperEtaSeconds,
        bytes parameters,
        address[] signers
    );
    event OperationVetoed(bytes32 indexed opId, bytes32 indexed opType);
    event OracleConfigSet(uint16 indexed index);
    event RepresentationConfigSet(
        ChainId chain, bytes32 indexed token, RepresentationConfig config
    );
    event RiskCouncilSet(address[] members, uint256 threshold);
    event Upgraded(address indexed implementation);

    function MAX_NEW_ASSET_LISTINGS() external view returns (uint256);
    function MAX_ORACLE_SOURCES() external view returns (uint256);
    function MAX_ORACLE_TLS_IDENTITIES() external view returns (uint256);
    function assetConfigFacet() external view returns (address);
    function credentialManager() external view returns (address);
    function domainSeparator() external view returns (bytes32);
    function executeDelayChange(
        bytes32 opId,
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function executeOperation(
        bytes32 opId,
        bytes32 opType,
        bytes memory params,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function executeUpgrade(
        bytes32 opId,
        address implementation,
        bytes memory migrationData,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
    function getAssetData(ChainId memory chainId, uint16 index, bytes32 assetAddress)
        external
        view
        returns (AssetData memory data);
    function getAssetIndex(ChainId memory chainId, bytes32 assetAddress)
        external
        view
        returns (uint32 index);
    function getAssets(uint16 start, uint16 end) external view returns (AssetData[] memory listings);
    function getOracleConfigs(uint16 start, uint16 end)
        external
        view
        returns (OracleConfig[] memory configs);
    function getRedemptionDelayParameters()
        external
        view
        returns (RedemptionDelayParameters memory parameters);
    function getRepresentationConfig(ChainId memory chain, bytes32 token)
        external
        view
        returns (RepresentationConfig memory config);
    function getRepresentationConfigs(uint16 start, uint16 end)
        external
        view
        returns (RepresentationEntry[] memory entries);
    function getRiskCouncil() external view returns (address[] memory members, uint256 threshold);
    function getRiskParameters(uint16 start, uint16 end)
        external
        view
        returns (RiskParameters[] memory parameters);
    function governanceNonces()
        external
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce);
    function initialize(
        uint256 _riskParameterChangeDelaySeconds,
        uint64 _upgradeDelaySeconds,
        address manager,
        bytes32 universeId,
        address[] memory members,
        uint256 threshold
    ) external;
    function oracleConfigFacet() external view returns (address);
    function pendingId(bytes32 pendingKey) external view returns (bytes32);
    function pendingUpgradeOperations()
        external
        view
        returns (bytes32 upgradeId, bytes32 delayChangeId);
    function proxiableUUID() external view returns (bytes32);
    function redemptionConfigFacet() external view returns (address);
    function representationConfigFacet() external view returns (address);
    function representationEntryCount() external view returns (uint256 count);
    function riskParameters(uint16)
        external
        view
        returns (
            uint8 collateralFactor,
            uint8 liabilityFactor,
            uint256 maxCollateral,
            uint256 maxOpenInterest,
            uint256 maxSpotOpenInterest,
            uint256 maxUtilization,
            bool isolatedOnly,
            uint256 skewModifier,
            uint256 skewCliff,
            int256 baseFundingRate,
            uint256 premiumClamp,
            uint256 maxFundingRate,
            uint256 maxBorrowRate,
            uint256 bufferMultiple,
            uint256 minSubAccountBalance,
            uint256 maxAdl
        );
    function scheduleDelayChange(
        bytes32 targetOpType,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        uint256 nonce,
        uint256 deadline,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32 opId);
    function scheduleOperation(
        bytes32 opType,
        bytes memory params,
        uint256 nonce,
        uint256 deadline,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32 opId);
    function scheduleUpgrade(
        address implementation,
        bytes32 migrationDataHash,
        uint256 nonce,
        uint256 deadline,
        address[] memory signers,
        bytes[] memory signatures
    ) external returns (bytes32);
    function upgradeDelayBounds() external view returns (DelayBounds memory);
    function upgradeDomainSeparator() external view returns (bytes32);
    function upgradeGovernanceNonces()
        external
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce);
    function upgradeOpType() external view returns (bytes32);
    function upgradeOperation(bytes32 opId) external view returns (Operation memory);
    function upgradeToAndCall(address newImplementation, bytes memory data) external payable;
    function validateRedemptionDelayParameters(RedemptionDelayParameters memory params)
        external
        view;
    function validateRiskParameters(RiskParameters memory params) external view;
    function vetoOperation(
        bytes32 opId,
        address[] memory councilSigners,
        bytes[] memory councilSignatures
    ) external;
}

