// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @notice Rules for a 32-byte chain address, where an EVM address fills the first 20 bytes.
library ChainAddress {
    /// @notice The routing ID of EVM chains.
    uint256 internal constant EVM_ROUTING_ID = 0;

    /// @notice An EVM address that is not left-aligned in its 32 bytes.
    /// @param chainAddress The rejected address.
    error AddressNotLeftAligned(bytes32 chainAddress);

    /// @notice Whether `chainAddress` is laid out as its chain expects.
    /// @param routingId The chain's routing ID.
    /// @param chainAddress The 32-byte address.
    /// @return aligned False only for an EVM address with nonzero bytes after its first 20.
    function isLeftAligned(uint256 routingId, bytes32 chainAddress)
        internal
        pure
        returns (bool aligned)
    {
        return routingId != EVM_ROUTING_ID || uint96(uint256(chainAddress)) == 0;
    }

    /// @notice Reverts with `AddressNotLeftAligned` unless `chainAddress` passes `isLeftAligned`.
    /// @param routingId The chain's routing ID.
    /// @param chainAddress The 32-byte address.
    function requireLeftAligned(uint256 routingId, bytes32 chainAddress) internal pure {
        if (!isLeftAligned(routingId, chainAddress)) revert AddressNotLeftAligned(chainAddress);
    }

    /// @notice The EVM address in `chainAddress`'s first 20 bytes.
    /// @dev Reverts with `AddressNotLeftAligned` unless `chainAddress` is a left-aligned EVM address.
    /// @param chainAddress The 32-byte address.
    /// @return evmAddress The EVM address.
    function toEvmAddress(bytes32 chainAddress) internal pure returns (address evmAddress) {
        requireLeftAligned(EVM_ROUTING_ID, chainAddress);
        return address(bytes20(chainAddress));
    }
}

