// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @notice Checks on piecewise series scaled so that 1_000_000 is one.
library SeriesValidation {
    /// @notice One, in the series' scale.
    uint256 internal constant ONE = 1_000_000;

    /// @notice Whether a series starts at zero, never decreases and stays at or below one.
    /// @param series The series checked.
    /// @return Whether the series is valid.
    function validateStartAtZeroIsAlwaysBelowOneAndIncreases(uint256[] memory series)
        internal
        pure
        returns (bool)
    {
        uint256 length = series.length;
        return
            length != 0 && series[0] == 0 && validateIncreases(series) && series[length - 1] <= ONE;
    }

    /// @notice Whether a series never decreases and stays at or below one.
    /// @param series The series checked.
    /// @return Whether the series is valid.
    function validateIncreasesAndBelowOne(uint256[] memory series) internal pure returns (bool) {
        uint256 length = series.length;
        return validateIncreases(series) && (length == 0 || series[length - 1] <= ONE);
    }

    /// @notice Whether a series is non-empty and ends at one.
    /// @param series The series checked.
    /// @return Whether the series is valid.
    function validateLastIsOne(uint256[] memory series) internal pure returns (bool) {
        uint256 length = series.length;
        return length != 0 && series[length - 1] == ONE;
    }

    /// @notice Whether a series never decreases.
    /// @param series The series checked.
    /// @return Whether the series is valid.
    function validateIncreases(uint256[] memory series) internal pure returns (bool) {
        for (uint256 position = 1; position < series.length; ++position) {
            if (series[position] < series[position - 1]) return false;
        }
        return true;
    }
}

src/utils/TPlusUUPSUpgradeable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Initializable} from "solady/utils/Initializable.sol";
import {UUPSUpgradeable} from "solady/utils/UUPSUpgradeable.sol";
import {GovernanceCore} from "../governance/GovernanceCore.sol";

/// @dev The upgrade's portable op type on every host. `upgradeOpType()` binds it to a deployment.
bytes32 constant UPGRADE_OP = keccak256("TPlusUUPSUpgradeable.UPGRADE");

/// @notice Shared UUPS upgradeability base for t+ contracts. An upgrade is a governance-core
///         operation: the operator committee signs its schedule, and the security council can
///         veto it or let it execute after the lower delay bound.
/// @dev Each host supplies the committee and the council through `_upgradeCommittee` and
///      `_upgradeCouncil`. The governance state lives in an
///      [ERC-7201](https://eips.ethereum.org/EIPS/eip-7201) namespace unless the host shares its
///      own through `_upgradeCore`. The upgrade's views are in `TPlusUpgradeViews`,
///      and the entry points that change its delay bounds and veto a pending operation are in
///      `TPlusUpgradeGovernance`; a host with views or entry points of its own over the same
///      state serves the upgrade through them. The base declares no ordinary storage, so it
///      does not move a host's slots.
abstract contract TPlusUUPSUpgradeable is Initializable, UUPSUpgradeable {
    using GovernanceCore for GovernanceCore.State;

    /// @notice Thrown when `upgradeToAndCall` is called outside `executeUpgrade`.
    error UpgradeNotAuthorized();

    /// @custom:storage-location erc7201:tplus.storage.TPlusUUPSUpgradeable.Governance
    struct UpgradeGovernanceStorage {
        /// @dev The governance state of the upgrade and its delay changes.
        GovernanceCore.State core;
        /// @dev The implementation `executeUpgrade` is installing, for `_authorizeUpgrade`.
        address authorizedImplementation;
    }

    // keccak256(abi.encode(uint256(keccak256("tplus.storage.TPlusUUPSUpgradeable.Governance")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant _UPGRADE_GOVERNANCE_STORAGE_SLOT =
        0xf867a70a81c0f09f508977aa8d8ac970d4d33d3b31856687e67d983417688a00;

    /// @dev Lock the implementation contract. Proxies can still initialize.
    constructor() {
        _disableInitializers();
    }

    /// @notice Schedules an upgrade pinned to the implementation's current code hash.
    /// @param implementation The new implementation, a UUPS implementation with code.
    /// @param migrationDataHash Hash of the call made on the new implementation after the switch.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadline Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return The operation's ID.
    function scheduleUpgrade(
        address implementation,
        bytes32 migrationDataHash,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32) {
        if (implementation.code.length == 0) revert UpgradeFailed();
        try UUPSUpgradeable(implementation).proxiableUUID() returns (bytes32 slot) {
            if (slot != _ERC1967_IMPLEMENTATION_SLOT) revert UpgradeFailed();
        } catch {
            revert UpgradeFailed();
        }
        bytes32 upgradeType = upgradeOpType();
        return _upgradeCore()
            .schedule(
                upgradeType,
                upgradeType,
                abi.encode(implementation, implementation.codehash, migrationDataHash),
                _upgradeCommittee(),
                nonce,
                deadline,
                signers,
                signatures
            );
    }

    /// @notice Executes a scheduled upgrade and runs its migration call.
    /// @param opId The operation's ID.
    /// @param implementation The scheduled implementation, with its scheduled code hash.
    /// @param migrationData The call whose hash was scheduled; empty skips the call.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeUpgrade(
        bytes32 opId,
        address implementation,
        bytes calldata migrationData,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        bytes32 upgradeType = upgradeOpType();
        _upgradeCore()
            .execute(
                opId,
                upgradeType,
                upgradeType,
                abi.encode(implementation, implementation.codehash, keccak256(migrationData)),
                _councilIfSigned(councilSigners, councilSignatures),
                councilSigners,
                councilSignatures
            );
        _upgradeGovernance().authorizedImplementation = implementation;
        upgradeToAndCall(implementation, migrationData);
    }

    /// @notice The op type upgrade approvals are signed and keyed under, bound to this chain and
    ///         this contract's address. Params `abi.encode(address implementation,
    ///         bytes32 codeHash, bytes32 migrationDataHash)`.
    /// @return The deployment op type of the upgrade.
    function upgradeOpType() public view returns (bytes32) {
        return GovernanceCore.deriveDeploymentOpType(UPGRADE_OP);
    }

    /// @dev Sets the universe upgrade approvals are signed in, once.
    function _initializeUpgradeUniverse(bytes32 universeId) internal {
        _upgradeCore().initializeUniverse(universeId);
    }

    /// @dev Sets both initial delay bounds of the upgrade to `delaySeconds`, once.
    function _initializeUpgradeDelay(uint64 delaySeconds) internal {
        _upgradeCore().initializeBounds(upgradeOpType(), delaySeconds, delaySeconds);
    }

    /// @dev Authorizes only the implementation `executeUpgrade` is installing, then clears it.
    function _authorizeUpgrade(address newImplementation) internal virtual override {
        UpgradeGovernanceStorage storage $ = _upgradeGovernance();
        address armedImplementation = $.authorizedImplementation;
        if (armedImplementation == address(0) || armedImplementation != newImplementation) {
            revert UpgradeNotAuthorized();
        }
        delete $.authorizedImplementation;
    }

    /// @dev The governance state upgrades and their delay changes run on. A host that already
    ///      holds a governance-core state overrides this to share it, and then sets its universe
    ///      itself instead of calling `_initializeUpgradeUniverse`.
    function _upgradeCore() internal view virtual returns (GovernanceCore.State storage) {
        return _upgradeGovernance().core;
    }

    /// @dev The operator committee whose signatures schedule an upgrade.
    function _upgradeCommittee() internal view virtual returns (GovernanceCore.Authority memory);

    /// @dev The security council whose signatures veto an upgrade or let it execute early.
    function _upgradeCouncil() internal view virtual returns (GovernanceCore.Authority memory);

    /// @dev The council for an execute: an unsigned one reads nothing from it.
    function _councilIfSigned(address[] calldata signers, bytes[] calldata signatures)
        internal
        view
        returns (GovernanceCore.Authority memory council)
    {
        if (signers.length == 0 && signatures.length == 0) {
            return GovernanceCore.Authority({isMember: _isNobody, threshold: 0});
        }
        return _upgradeCouncil();
    }

    function _isNobody(address) private pure returns (bool) {
        return false;
    }

    function _upgradeGovernance() private pure returns (UpgradeGovernanceStorage storage $) {
        bytes32 slot = _UPGRADE_GOVERNANCE_STORAGE_SLOT;
        /// @solidity memory-safe-assembly
        assembly {
            $.slot := slot
        }
    }
}

src/utils/TPlusUpgradeGovernance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {GovernanceCore} from "../governance/GovernanceCore.sol";
import {TPlusUpgradeViews} from "./TPlusUpgradeViews.sol";

/// @notice The entry points that change the delay bounds of a `TPlusUUPSUpgradeable` host's
///         upgrade and veto its pending operations, for a host whose only governance-core
///         operation is its upgrade.
/// @dev The Registry does not inherit this: its own delay-change and veto entry points run on
///      the state its upgrades share.
abstract contract TPlusUpgradeGovernance is TPlusUpgradeViews {
    using GovernanceCore for GovernanceCore.State;

    /// @notice Schedules a change of the upgrade's delay bounds, waiting its current bounds.
    /// @param lowerSeconds The new lower bound.
    /// @param upperSeconds The new upper bound.
    /// @param nonce The nonce the approval was signed with, above the last accepted one.
    /// @param deadline Last timestamp at which the approval may be submitted.
    /// @param signers Committee members in strictly ascending order.
    /// @param signatures Their signatures over the schedule digest.
    /// @return The operation's ID.
    function scheduleUpgradeDelayChange(
        uint64 lowerSeconds,
        uint64 upperSeconds,
        uint256 nonce,
        uint256 deadline,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external returns (bytes32) {
        return _upgradeCore()
            .scheduleDelayChange(
                upgradeOpType(),
                lowerSeconds,
                upperSeconds,
                _upgradeCommittee(),
                nonce,
                deadline,
                signers,
                signatures
            );
    }

    /// @notice Executes a scheduled change of the upgrade's delay bounds.
    /// @param opId The operation's ID.
    /// @param lowerSeconds The scheduled lower bound.
    /// @param upperSeconds The scheduled upper bound.
    /// @param councilSigners Council members in strictly ascending order, or empty.
    /// @param councilSignatures Their signatures over the execute digest, or empty.
    function executeUpgradeDelayChange(
        bytes32 opId,
        uint64 lowerSeconds,
        uint64 upperSeconds,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        _upgradeCore()
            .executeDelayChange(
                opId,
                upgradeOpType(),
                lowerSeconds,
                upperSeconds,
                _councilIfSigned(councilSigners, councilSignatures),
                councilSigners,
                councilSignatures
            );
    }

    /// @notice Cancels a pending upgrade or delay change with council approval.
    /// @param opId The pending operation's ID.
    /// @param councilSigners Council members in strictly ascending order.
    /// @param councilSignatures Their signatures over the veto digest.
    function vetoUpgradeOperation(
        bytes32 opId,
        address[] calldata councilSigners,
        bytes[] calldata councilSignatures
    ) external {
        _upgradeCore().veto(opId, _upgradeCouncil(), councilSigners, councilSignatures);
    }
}

src/utils/TPlusUpgradeViews.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {GovernanceCore} from "../governance/GovernanceCore.sol";
import {TPlusUUPSUpgradeable} from "./TPlusUUPSUpgradeable.sol";

/// @notice The views of the upgrade's governance state, for a `TPlusUUPSUpgradeable` host with no
///         views of its own over that state for every operation.
abstract contract TPlusUpgradeViews is TPlusUUPSUpgradeable {
    using GovernanceCore for GovernanceCore.State;

    /// @notice The upgrade's delay bounds.
    /// @return The bounds.
    function upgradeDelayBounds() external view returns (GovernanceCore.DelayBounds memory) {
        return _upgradeCore().delayBounds(upgradeOpType());
    }

    /// @notice The pending upgrade and the pending change of its delay bounds; zero when none is.
    /// @return upgradeId The pending upgrade's ID.
    /// @return delayChangeId The pending delay change's ID.
    function pendingUpgradeOperations()
        external
        view
        returns (bytes32 upgradeId, bytes32 delayChangeId)
    {
        GovernanceCore.State storage core = _upgradeCore();
        bytes32 upgradeType = upgradeOpType();
        return
            (
                core.pendingId(upgradeType),
                core.pendingId(GovernanceCore.delayChangeKey(upgradeType))
            );
    }

    /// @notice An upgrade or delay-change operation by ID.
    /// @param opId The operation's ID.
    /// @return The operation.
    function upgradeOperation(bytes32 opId)
        external
        view
        returns (GovernanceCore.Operation memory)
    {
        return _upgradeCore().operation(opId);
    }

    /// @notice The nonces of upgrade approvals.
    /// @return lastScheduleNonce The highest schedule nonce accepted; sign a schedule above it.
    /// @return nextCouncilNonce The nonce the next council execute or veto signs.
    function upgradeGovernanceNonces()
        external
        view
        returns (uint256 lastScheduleNonce, uint256 nextCouncilNonce)
    {
        return _upgradeCore().governanceNonces();
    }

    /// @notice [EIP-712](https://eips.ethereum.org/EIPS/eip-712) domain separator upgrade
    ///         approvals are signed under.
    /// @return The domain separator.
    function upgradeDomainSeparator() public view returns (bytes32) {
        return _upgradeCore().domainSeparator();
    }
}
